                            <button
                                type="button"
                                onClick={handleClearForm}
                                className="flex items-center gap-1.5 px-3 py-1.5 text-xs bg-red-900/20 hover:bg-red-900/40 text-red-400 border border-red-900/50 rounded-md transition-colors"
                            >
                                <TrashIcon />
                                {t.clearBtn}
