                             <div className="md:col-span-2 pt-6 border-t border-cyan-900/30">
                                <DynamicVariables 
                                    variables={variables}
                                    onAdd={handleAddVariable}
                                    onUpdate={handleUpdateVariable}
                                    onDelete={handleDeleteVariable}
