// --- Main App Component ---
const App: React.FC = () => {
    const [promptData, setPromptData] = useState<VoiceAgentPromptData>({
        agentRole: '',
        personality: '',
        toneAndLanguage: '',
        responseGuidelines: '',
        task: '',
        context: '',
        stepByStep: '',
        notes: '',
    });
    const [variables, setVariables] = useState<DynamicVariable[]>([]);
    const [niche, setNiche] = useState('');
    const [generatedPrompt, setGeneratedPrompt] = useState<string>('');
    const [isLoading, setIsLoading] = useState<boolean>(false);
    const [error, setError] = useState<string | null>(null);
    const [isCopied, setIsCopied] = useState<boolean>(false);
    const [listeningField, setListeningField] = useState<string | null>(null);
    const [micSupported, setMicSupported] = useState<boolean>(false);
    const [language, setLanguage] = useState<Language>('es');

    // Suggestions State
    const [suggestionModalOpen, setSuggestionModalOpen] = useState(false);
    const [isGeneratingSuggestion, setIsGeneratingSuggestion] = useState(false);
    const [suggestions, setSuggestions] = useState<string[]>([]);
    const [activeSuggestionField, setActiveSuggestionField] = useState<'responseGuidelines' | 'stepByStep' | 'notes' | null>(null);

    const recognitionRef = useRef<any | null>(null);
    const formRef = useRef<HTMLDivElement>(null);

    const [history, setHistory] = useState<PromptHistoryItem[]>([]);
    const [toastMessage, setToastMessage] = useState('');

    const [autoSavedData, setAutoSavedData] = useState<AutoSavedDraft | null>(null);
    const [isShareModalOpen, setIsShareModalOpen] = useState(false);
    const [shareableLink, setShareableLink] = useState('');

    // CRITICAL: This state ensures we don't overwrite localStorage with empty data before loading completes.
    const [isInitialized, setIsInitialized] = useState(false);

    const promptDataRef = useRef(promptData);
    promptDataRef.current = promptData;
    const variablesRef = useRef(variables);
    variablesRef.current = variables;

    const t = translations[language];

    const toggleLanguage = () => {
        setLanguage(prev => prev === 'es' ? 'en' : 'es');
    };


    // Auto-save logic
    useEffect(() => {
        const intervalId = setInterval(() => {
            const currentData = promptDataRef.current;
            const currentVariables = variablesRef.current;
            const isDataEmpty = Object.values(currentData).every(value => value === '');
            const areVariablesEmpty = currentVariables.length === 0;

            if (!isDataEmpty || !areVariablesEmpty) {
                localStorage.setItem('autoSavedPrompt', JSON.stringify({ promptData: currentData, variables: currentVariables }));
            }
        }, 10000); // Save every 10 seconds for better data safety

        return () => clearInterval(intervalId);
    }, []);

    // Load history, auto-saved prompt, and API keys on initial render
    useEffect(() => {
        const initializeApp = () => {
            try {
                // 1. ALWAYS Load history first to prevent data loss
                const savedHistory = localStorage.getItem('promptHistory');
                if (savedHistory) {
                    const parsedHistory = JSON.parse(savedHistory);
                    if (Array.isArray(parsedHistory)) {
                        setHistory(parsedHistory);
                    }
                }

                // 2. Check for shared prompt in URL
                const hash = window.location.hash;
                if (hash.startsWith('#prompt=')) {
                    try {
                        const encodedData = hash.substring('#prompt='.length);
                        // Fix for Unicode decoding
                        const decodedData = decodeURIComponent(escape(atob(encodedData)));
                        const sharedData: Partial<ShareablePromptData> = JSON.parse(decodedData);

                        const initialPromptData = {
                            agentRole: '', personality: '', toneAndLanguage: '', 
                            responseGuidelines: '', task: '', context: '', 
                            stepByStep: '', notes: ''
                        };

                        setPromptData(sharedData.promptData || initialPromptData);
                        setVariables(sharedData.variables || []);
                        setNiche(sharedData.niche || '');
                        setGeneratedPrompt(sharedData.generatedPrompt || '');

                        setToastMessage('¡Prompt compartido cargado con éxito!');
                        setTimeout(() => setToastMessage(''), 3000);

                        // Clean the URL
                        window.history.replaceState(null, '', ' ');

                        // If we loaded from URL, we skip loading autosave draft to avoid conflict
                        return; 
                    } catch (err) {
                        console.error("Error loading shared prompt", err);
                        // If URL load fails, continue to load autosave
                    }
                }

                // 3. Load AutoSave (only if no shared prompt was loaded)
                const savedPrompt = localStorage.getItem('autoSavedPrompt');
                if (savedPrompt) {
                    setAutoSavedData(JSON.parse(savedPrompt));
                }

            } catch (e) { 
                console.error("Failed to load data from localStorage or URL", e); 
            } finally {
                // Mark initialization as complete, allowing saves to occur
                setIsInitialized(true);
            }
        };

        initializeApp();
    }, []);

    // Persist history to localStorage whenever it changes, BUT ONLY after initialization
    useEffect(() => {
        if (!isInitialized) return; // CRITICAL: Prevent saving empty history on initial render before load

        try {
            localStorage.setItem('promptHistory', JSON.stringify(history));
        } catch (e) { console.error("Failed to save history to localStorage", e); }
    }, [history, isInitialized]);


    // Speech Recognition Setup
    useEffect(() => {
        const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
        if (SpeechRecognition) {
            setMicSupported(true);
            const recognition = new SpeechRecognition();
            recognition.continuous = true;
            recognition.lang = language === 'es' ? 'es-ES' : 'en-US';
            recognition.interimResults = true;

            recognition.onresult = (event: any) => {
                 let finalTranscript = '';
                for (let i = event.resultIndex; i < event.results.length; ++i) {
                    if (event.results[i].isFinal) {
                        finalTranscript += event.results[i][0].transcript;
                    }
                }
                if (listeningField && finalTranscript) {
                    if (listeningField in promptDataRef.current) {
                        setPromptData(prev => ({
                            ...prev,
                            [listeningField]: (prev[listeningField as keyof VoiceAgentPromptData] ? prev[listeningField as keyof VoiceAgentPromptData] + ' ' : '') + finalTranscript
                        }));
                    } else if (listeningField === 'niche') {
                        setNiche(prev => (prev ? prev + ' ' : '') + finalTranscript);
                    } else if (listeningField.startsWith('variable-')) {
                        const [, field, id] = listeningField.split('-');
                        setVariables(prevVars => prevVars.map(v => {
                            if (v.id === id) {
                                if (field === 'name') {
                                    const newValue = (v.name + finalTranscript).replace(/[^a-zA-Z0-9_]/g, '');
                                    return { ...v, name: newValue };
                                }
                                if (field === 'value') {
                                    const newValue = (v.value ? v.value + ' ' : '') + finalTranscript;
                                    return { ...v, value: newValue };
                                }
                            }
                            return v;
                        }));
                    }
                }
            };
            recognition.onerror = (event: any) => { console.error('Speech recognition error', event.error); setListeningField(null); };
            recognition.onend = () => { if (listeningField) { setListeningField(null); } };
            recognitionRef.current = recognition;
        } else {
            setMicSupported(false);
        }
    }, [listeningField, language]);


    const handleInputChange = useCallback((field: keyof VoiceAgentPromptData, value: string) => {
        setPromptData(prev => ({ ...prev, [field]: value }));
    }, []);

    const handleMicClick = (field: string) => {
        if (!recognitionRef.current) return;
        if (listeningField === field) {
            recognitionRef.current.stop();
            setListeningField(null);
        } else {
            if (listeningField) { recognitionRef.current.stop(); }
            setListeningField(field);
            recognitionRef.current.start();
        }
    };

    const handleSelectExample = (data: VoiceAgentPromptData) => {
        setPromptData(data);
        setGeneratedPrompt('');
        setNiche('');
        setError(null);
        setVariables([]);
        formRef.current?.scrollIntoView({ behavior: 'smooth' });
        setToastMessage('Plantilla cargada. ¡Ya puedes editarla!');
        setTimeout(() => setToastMessage(''), 3000);
    };

    const handleSaveToHistory = () => {
        const trimmedNiche = niche.trim();
        const minLength = 3;

        if (trimmedNiche.length < minLength) {
            setError(`El campo '${t.nicheLabel}' es obligatorio y debe tener al menos ${minLength} caracteres.`);
            return;
        }

        if (!generatedPrompt) {
            setError("No hay ningún prompt generado para guardar.");
            return;
        }
        setError(null);

        const newHistoryItem: PromptHistoryItem = {
            id: new Date().toISOString(),
            promptData,
            generatedPrompt,
            timestamp: Date.now(),
            niche: trimmedNiche,
            variables,
        };

        const isDuplicate = history.some(item => 
            item.generatedPrompt === newHistoryItem.generatedPrompt && 
            JSON.stringify(item.promptData) === JSON.stringify(newHistoryItem.promptData) &&
            item.niche === newHistoryItem.niche
        );

        if (isDuplicate) {
            setToastMessage('Este prompt ya está en tu historial.');
            setTimeout(() => setToastMessage(''), 3000);
            return;
        }

        setHistory(prevHistory => [newHistoryItem, ...prevHistory]);
        setToastMessage('Prompt guardado en la base de datos');
        setTimeout(() => setToastMessage(''), 3000);
    };

    const handleSubmit = async (e: React.FormEvent) => {
        e.preventDefault();


        const trimmedRole = promptData.agentRole.trim();
        const trimmedTask = promptData.task.trim();
        const trimmedNiche = niche.trim();
        const minLength = 3;

        if (trimmedRole.length < minLength) {
            setError(`El campo '${t.roleLabel}' es obligatorio y debe tener al menos ${minLength} caracteres.`);
            return;
        }

        if (trimmedTask.length < minLength) {
            setError(`El campo '${t.taskLabel}' es obligatorio y debe tener al menos ${minLength} caracteres.`);
            return;
        }

        if (trimmedNiche.length < minLength) {
            setError(`El campo '${t.nicheLabel}' es obligatorio y debe tener al menos ${minLength} caracteres.`);
            return;
        }

        setIsLoading(true);
        setError(null);
        setGeneratedPrompt('');

        // Substitute variables before sending to the API
        const substitutedPromptData = { ...promptData };
        for (const variable of variables) {
            if (variable.name) {
                const regex = new RegExp(`{{${variable.name}}}`, 'g');
                for (const key in substitutedPromptData) {
                    substitutedPromptData[key as keyof VoiceAgentPromptData] = 
                        substitutedPromptData[key as keyof VoiceAgentPromptData].replace(regex, variable.value);
                }
            }
        }


        try {
            const perfectPrompt = await generatePerfectPrompt(substitutedPromptData);
            setGeneratedPrompt(perfectPrompt);

            // NOTE: Auto-save logic removed. The user must manually click "Save to DB".
            // This prevents duplication conflicts when clicking the save button immediately after generation.

            // Clear auto-saved data on successful submission
            localStorage.removeItem('autoSavedPrompt');
            setAutoSavedData(null);
            // We do NOT clear niche here anymore to allow the user to save with the current niche

        } catch (err) {
            const errorMessage = (err as Error).message;
            setError(errorMessage);
            console.error(err);
        } finally {
            setIsLoading(false);
        }
    };

    const handleCopy = () => {
        if (generatedPrompt) {
            navigator.clipboard.writeText(generatedPrompt);
            setIsCopied(true);
            setTimeout(() => setIsCopied(false), 2000);
        }
    };

    const handleDownloadMarkdown = () => {
        if (!generatedPrompt) return;

        try {
            const blob = new Blob([generatedPrompt], { type: 'text/markdown;charset=utf-8' });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = `prompt-${(niche || 'agent').replace(/\s+/g, '-').toLowerCase()}.md`;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);

            setToastMessage('Descargando archivo Markdown...');
            setTimeout(() => setToastMessage(''), 2000);
        } catch (e) {
            console.error("Download failed", e);
            setError("Error al descargar el archivo.");
        }
    };

    const handleExportPdf = () => {
        // Find the content to print
        const content = document.querySelector('#generated-prompt-print-area .prompt-content-for-print');

        if (!content) {
            console.error("No print content found");
            setToastMessage("Error: No hay contenido para imprimir");
            return;
        }

        // Create a hidden iframe
        const iframe = document.createElement('iframe');
        iframe.style.position = 'fixed';
        iframe.style.right = '0';
        iframe.style.bottom = '0';
        iframe.style.width = '0';
        iframe.style.height = '0';
        iframe.style.border = '0';
        document.body.appendChild(iframe);

        const doc = iframe.contentWindow?.document;
        if (!doc) return;

        // Build the full HTML document for the iframe
        doc.open();
        doc.write(`
            <!DOCTYPE html>
            <html>
            <head>
                <title>System Prompt - ${niche || 'Generado'}</title>
                <style>
                    body {
                        font-family: 'Helvetica', 'Arial', sans-serif;
                        color: #000;
                        background: #fff;
                        padding: 40px;
                        line-height: 1.6;
                        font-size: 12pt;
                    }
                    h1 { 
                        font-size: 24px; 
                        border-bottom: 2px solid #000; 
                        padding-bottom: 10px; 
                        margin-bottom: 30px; 
                    }
                    h2 { 
                        font-size: 18px; 
                        color: #000;
                        border-bottom: 1px solid #ccc;
                        padding-bottom: 5px;
                        margin-top: 25px;
                        text-transform: uppercase;
                        letter-spacing: 1px;
                    }
                    h3 { font-size: 16px; margin-top: 20px; font-weight: bold; }
                    p { margin-bottom: 15px; }
                    ul, ol { margin-left: 20px; margin-bottom: 15px; }
                    li { margin-bottom: 5px; }
                    pre {
                        background: #f4f4f4;
                        border: 1px solid #ddd;
                        padding: 15px;
                        border-radius: 5px;
                        white-space: pre-wrap;
                        font-family: 'Courier New', monospace;
                        font-size: 11px;
                        color: #000;
                    }
                    code {
                        background: #f4f4f4;
                        padding: 2px 5px;
                        font-family: 'Courier New', monospace;
                        font-size: 0.9em;
                    }
                    blockquote {
                        border-left: 4px solid #333;
                        margin: 0;
                        padding-left: 15px;
                        color: #444;
                        font-style: italic;
                    }
                </style>
            </head>
            <body>
                <h1>System Prompt: ${niche || 'Agente IA'}</h1>
                ${content.innerHTML}
            </body>
            </html>
        `);
        doc.close();

        // Wait for content to load then print
        iframe.onload = () => {
            // Small delay to ensure styles are applied
            setTimeout(() => {
                iframe.contentWindow?.focus();
                iframe.contentWindow?.print();

                // Remove iframe after printing
                // We use a longer timeout to ensure the print dialog has opened
                setTimeout(() => {
                    document.body.removeChild(iframe);
                }, 1000);
            }, 500);
        };
    };

    const handleOpenShareModal = () => {
        if (!generatedPrompt) return;

        try {
            const shareData: ShareablePromptData = {
                promptData,
                generatedPrompt,
                niche,
                variables,
            };
            const jsonString = JSON.stringify(shareData);

            // Fix for Unicode encoding: encode to UTF-8 then base64
            const encodedData = btoa(unescape(encodeURIComponent(jsonString)));
            const url = `${window.location.href.split('#')[0]}#prompt=${encodedData}`;

            setShareableLink(url);
            setIsShareModalOpen(true);
        } catch (error) {
            console.error("Error creating share link:", error);
            setError("No se pudo crear el enlace para compartir.");
        }
    };

    const handleSelectHistoryItem = (item: PromptHistoryItem) => {
        setPromptData(item.promptData);
        setGeneratedPrompt(item.generatedPrompt);
        setNiche(item.niche);
        setVariables(item.variables || []);
        formRef.current?.scrollIntoView({ behavior: 'smooth' });
    };

    const handleDeleteHistoryItem = (id: string) => {
        if (window.confirm('¿Estás seguro de que quieres borrar este prompt?')) {
            setHistory(prev => prev.filter(item => item.id !== id));
            setToastMessage('Prompt eliminado.');
            setTimeout(() => setToastMessage(''), 3000);
        }
    };

    const handleRestoreAutoSave = () => {
        if (autoSavedData) {
            setPromptData(autoSavedData.promptData);
            setVariables(autoSavedData.variables || []);
            setAutoSavedData(null);
            localStorage.removeItem('autoSavedPrompt');
        }
    };

    const handleDismissAutoSave = () => {
        localStorage.removeItem('autoSavedPrompt');
        setAutoSavedData(null);
    };

    const handleClearForm = () => {
        setPromptData({
            agentRole: '', personality: '', toneAndLanguage: '', responseGuidelines: '',
            task: '', context: '', stepByStep: '', notes: '',
        });
        setNiche('');
        setGeneratedPrompt('');
        setError(null);
        setVariables([]);
        localStorage.removeItem('autoSavedPrompt');
        setAutoSavedData(null);
    };

    // --- Dynamic Variable Handlers ---
    const handleAddVariable = () => {
        setVariables(prev => [...prev, { id: Date.now().toString(), name: '', value: '' }]);
    };

    const handleUpdateVariable = (id: string, field: 'name' | 'value', fieldValue: string) => {
        setVariables(prev => prev.map(v => v.id === id ? { ...v, [field]: fieldValue } : v));
    };

    const handleDeleteVariable = (id: string) => {
        setVariables(prev => prev.filter(v => v.id !== id));
    };

    // Handle variable edits coming from the Markdown Editor (click on {{variable}})
    const handleVariableEditFromEditor = (oldName: string, newName: string, newValue: string) => {
        if (oldName !== newName) {
            const regex = new RegExp(`{{${oldName}}}`, 'g');
            setGeneratedPrompt(prev => prev.replace(regex, `{{${newName}}}`));
        }

        setVariables(prev => {
            const existingIndex = prev.findIndex(v => v.name === oldName);

            if (existingIndex >= 0) {
                const updated = [...prev];
                updated[existingIndex] = { 
                    ...updated[existingIndex], 
                    name: newName, 
                    value: newValue 
                };
                return updated;
            } else {
                return [...prev, { 
                    id: Date.now().toString(), 
                    name: newName, 
                    value: newValue 
                }];
            }
        });

        setToastMessage('Variable actualizada');
        setTimeout(() => setToastMessage(''), 2000);
    };

    // --- Auto Generation Handlers ---
    const handleAutoGenerate = async (field: 'responseGuidelines' | 'stepByStep' | 'notes') => {
        // Prerequisite check
        if (!promptData.agentRole || !promptData.task) {
            setError(t.errorPrerequisites);
            return;
        }
        setError(null);

        setActiveSuggestionField(field);
        setSuggestionModalOpen(true);
        setIsGeneratingSuggestion(true);
        setSuggestions([]);

        try {
            const result = await generateSuggestions(promptData, field, language);
            setSuggestions(result);
        } catch (e) {
            console.error(e);
            setError("Error generating suggestions. Please try again.");
            setSuggestionModalOpen(false);
        } finally {
            setIsGeneratingSuggestion(false);
        }
    };

    const handleSelectSuggestion = (value: string) => {
        if (activeSuggestionField) {
            handleInputChange(activeSuggestionField, value);
            setSuggestionModalOpen(false);
            setToastMessage('Contenido insertado correctamente');
            setTimeout(() => setToastMessage(''), 2000);
        }
    };


    return (
        <div className="min-h-screen bg-gray-50 text-gray-800 flex flex-col items-center p-4 sm:p-6 lg:p-8 font-sans">
            <Toast message={toastMessage} show={!!toastMessage} />
            <ShareModal isOpen={isShareModalOpen} onClose={() => setIsShareModalOpen(false)} link={shareableLink} lang={language} />
            <SuggestionModal 
                isOpen={suggestionModalOpen} 
                onClose={() => setSuggestionModalOpen(false)} 
                onSelect={handleSelectSuggestion}
                loading={isGeneratingSuggestion}
                suggestions={suggestions}
                lang={language}
            />

            {/* Language Toggle */}
            <div className="absolute top-4 right-4 z-50 no-print">
                <button 
                    onClick={toggleLanguage}
                    className="flex items-center gap-2 px-3 py-1.5 bg-white border border-gray-200 rounded-lg text-xs font-semibold text-gray-600 hover:text-blue-600 hover:border-blue-500/50 transition-all shadow-sm"
                >
                    <LanguageIcon />
                    <span>{language === 'es' ? 'ESPAÑOL' : 'ENGLISH'}</span>
                </button>
            </div>

            <div className="w-full max-w-5xl mx-auto mb-20">
                <header className="relative text-center mb-12 no-print">
                    <div className="flex justify-center items-center gap-3 sm:gap-4 mb-2">
                        <Logo />
                        <h1 className="text-4xl sm:text-5xl font-bold text-transparent bg-clip-text bg-gradient-to-r from-blue-600 to-indigo-600 tracking-tight">
                            VoxWizard IA
                        </h1>
                    </div>
                    <p className="text-blue-600 font-mono text-sm uppercase tracking-widest font-semibold">
                        {t.subtitle}
                    </p>
                    <p className="mt-4 text-lg text-gray-600 max-w-2xl mx-auto">
                        {t.description}
                    </p>
                </header>

                <PromptExamples onSelectExample={handleSelectExample} lang={language} />

                <main ref={formRef} className="bg-white p-6 sm:p-8 rounded-2xl border border-gray-200 shadow-xl mt-12 no-print relative overflow-hidden">
                    {/* Decorative top border */}
                    <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-500 to-indigo-500"></div>

                    {autoSavedData && (
                        <AutoSaveNotification
                            onRestore={handleRestoreAutoSave}
                            onDismiss={handleDismissAutoSave}
                            lang={language}
                        />
                    )}

                    <form onSubmit={handleSubmit}>
                        <div className="flex justify-between items-center mb-6 border-b border-gray-100 pb-4">
                            <h2 className="text-xl font-bold text-gray-800 uppercase tracking-wide flex items-center gap-2">
                                <span className="w-2 h-2 bg-blue-500 rounded-full"></span>
                                {t.configTitle}
                            </h2>
                            <button
                                type="button"
                                onClick={handleClearForm}
                                className="flex items-center gap-1.5 px-3 py-1.5 text-xs bg-red-50 hover:bg-red-100 text-red-600 border border-red-200 rounded-md transition-colors"
                            >
                                <TrashIcon />
                                {t.clearBtn}
                            </button>
                        </div>
                        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                            <div className="md:col-span-2">
                                <InputField
                                    label={t.roleLabel}
                                    value={promptData.agentRole}
                                    onChange={(e) => handleInputChange('agentRole', e.target.value)}
                                    placeholder={t.rolePlaceholder}
                                    helpText={t.roleHelp}
                                    required
                                    onMicClick={() => handleMicClick('agentRole')}
                                    isListening={listeningField === 'agentRole'}
                                    micSupported={micSupported}
                                />
                            </div>
                            <div className="md:col-span-2">
                                <InputField
                                    label={t.taskLabel}
                                    value={promptData.task}
                                    onChange={(e) => handleInputChange('task', e.target.value)}
                                    placeholder={t.taskPlaceholder}
                                    helpText={t.taskHelp}
                                    required
                                    onMicClick={() => handleMicClick('task')}
                                    isListening={listeningField === 'task'}
                                    micSupported={micSupported}
                                />
                            </div>
                            <InputField
                                label={t.personalityLabel}
                                value={promptData.personality}
                                onChange={(e) => handleInputChange('personality', e.target.value)}
                                placeholder={t.personalityPlaceholder}
                                helpText={t.personalityHelp}
                                onMicClick={() => handleMicClick('personality')}
                                isListening={listeningField === 'personality'}
                                micSupported={micSupported}
                            />
                             <InputField
                                label={t.toneLabel}
                                value={promptData.toneAndLanguage}
                                onChange={(e) => handleInputChange('toneAndLanguage', e.target.value)}
                                placeholder={t.tonePlaceholder}
                                helpText={t.toneHelp}
                                onMicClick={() => handleMicClick('toneAndLanguage')}
                                isListening={listeningField === 'toneAndLanguage'}
                                micSupported={micSupported}
                            />
                            <div className="md:col-span-2">
                                <InputField
                                    label={t.contextLabel}
                                    value={promptData.context}
                                    onChange={(e) => handleInputChange('context', e.target.value)}
                                    placeholder={t.contextPlaceholder}
                                    helpText={t.contextHelp}
                                    isTextarea
                                    onMicClick={() => handleMicClick('context')}
                                    isListening={listeningField === 'context'}
                                    micSupported={micSupported}
                                />
                            </div>
                            <InputField
                                label={t.guidelinesLabel}
                                value={promptData.responseGuidelines}
                                onChange={(e) => handleInputChange('responseGuidelines', e.target.value)}
                                placeholder={t.guidelinesPlaceholder}
                                helpText={t.guidelinesHelp}
                                isTextarea
                                onMicClick={() => handleMicClick('responseGuidelines')}
                                isListening={listeningField === 'responseGuidelines'}
                                micSupported={micSupported}
                                onAutoGenerate={() => handleAutoGenerate('responseGuidelines')}
                            />
                            <InputField
                                label={t.stepByStepLabel}
                                value={promptData.stepByStep}
                                onChange={(e) => handleInputChange('stepByStep', e.target.value)}
                                placeholder={t.stepByStepPlaceholder}
                                helpText={t.stepByStepHelp}
                                isTextarea
                                onMicClick={() => handleMicClick('stepByStep')}
                                isListening={listeningField === 'stepByStep'}
                                micSupported={micSupported}
                                onAutoGenerate={() => handleAutoGenerate('stepByStep')}
                            />
                            <div className="md:col-span-2">
                                <InputField
                                    label={t.notesLabel}
                                    value={promptData.notes}
                                    onChange={(e) => handleInputChange('notes', e.target.value)}
                                    placeholder={t.notesPlaceholder}
                                    helpText={t.notesHelp}
                                    onMicClick={() => handleMicClick('notes')}
                                    isListening={listeningField === 'notes'}
                                    micSupported={micSupported}
                                    onAutoGenerate={() => handleAutoGenerate('notes')}
                                />
                            </div>

                             <div className="md:col-span-2 pt-6 border-t border-gray-100">
                                <InputField
                                    label={t.nicheLabel}
                                    value={niche}
                                    onChange={(e) => setNiche(e.target.value)}
                                    placeholder={t.nichePlaceholder}
                                    helpText={t.nicheHelp}
                                    required
                                    onMicClick={() => handleMicClick('niche')}
                                    isListening={listeningField === 'niche'}
                                    micSupported={micSupported}
                                />
                            </div>

                             <div className="md:col-span-2 pt-6 border-t border-gray-100">
                                <DynamicVariables 
                                    variables={variables}
                                    onAdd={handleAddVariable}
                                    onUpdate={handleUpdateVariable}
                                    onDelete={handleDeleteVariable}
                                    onMicClick={handleMicClick}
                                    listeningField={listeningField}
                                    micSupported={micSupported}
                                    lang={language}
                                />
                            </div>

                        </div>
                        {error && <p className="text-red-500 text-center mt-4 bg-red-50 p-2 rounded border border-red-200">{error}</p>}
                        <div className="mt-8 flex flex-col sm:flex-row justify-center items-center gap-4">
                            <button
                                type="submit"
                                disabled={isLoading}
                                className="flex items-center justify-center gap-2 w-full sm:w-auto px-8 py-3 bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-700 hover:to-indigo-700 text-white font-bold rounded-lg shadow-lg shadow-blue-500/20 transition-all duration-300 ease-in-out transform hover:scale-105 disabled:opacity-50 disabled:cursor-not-allowed disabled:scale-100"
                            >
                                {isLoading ? <Spinner /> : <SparklesIcon />}
                                {isLoading ? t.processingBtn : t.processBtn}
                            </button>
                             {generatedPrompt && !isLoading && (
                                <button
                                    type="button"
                                    onClick={handleSaveToHistory}
                                    className="flex items-center justify-center gap-2 w-full sm:w-auto px-6 py-3 bg-gray-100 hover:bg-gray-200 border border-gray-300 text-gray-700 font-semibold rounded-lg shadow-sm transition-colors duration-200"
                                    aria-label="Guardar el prompt actual en el historial"
                                >
                                    <PlusIcon />
                                    {t.saveDbBtn}
                                </button>
                            )}
                        </div>
                    </form>
                </main>

                {(isLoading || generatedPrompt) && (
                    <div id="generated-prompt-print-area" className="mt-10">
                         <div className="print-header-content hidden">
                            <h2>{t.generatedTitle}</h2>
                        </div>
                        <h2 className="text-2xl font-bold text-center mb-4 text-blue-600 no-print uppercase tracking-wide">
                             {t.generatedTitle}
                        </h2>
                        <div className="relative bg-white p-6 rounded-xl border border-gray-200 min-h-[150px] shadow-xl">
                            {/* Header color strip */}
                            <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-500 to-indigo-500"></div>

                            {isLoading ? (
                                <div className="flex flex-col items-center justify-center h-32 gap-4">
                                    <div className="text-blue-600">
                                        <Spinner />
                                    </div>
                                    <div className="animate-pulse text-blue-500 font-mono text-sm">{t.processingAgent}</div>
                                </div>
                            ) : (
                                <>
                                    <div className="absolute top-4 right-4 flex gap-2 no-print z-10">
                                        <IconButton
                                            onClick={handleOpenShareModal}
                                            text={t.shareBtn}
                                            icon={<ShareIcon />}
                                            className="bg-gray-100 hover:bg-gray-200 text-gray-700 border border-gray-300"
                                        />
                                        <IconButton
                                            onClick={handleCopy}
                                            text={isCopied ? t.copiedBtn : t.copyBtn}
                                            icon={isCopied ? <CheckIcon /> : <CopyIcon />}
                                            className={isCopied ? 'bg-green-100 text-green-700 border border-green-300' : 'bg-gray-100 hover:bg-gray-200 text-gray-700 border border-gray-300'}
                                        />
                                        <IconButton
                                            onClick={handleDownloadMarkdown}
                                            text="MD"
                                            icon={<DownloadIcon />}
                                            className="bg-gray-100 hover:bg-gray-200 text-gray-700 border border-gray-300"
                                        />
                                        <IconButton
                                            onClick={handleExportPdf}
                                            text="Guardar PDF"
                                            icon={<PdfIcon />}
                                            className="bg-gray-100 hover:bg-gray-200 text-gray-700 border border-gray-300"
                                        />
                                    </div>
                                    <MarkdownEditor 
                                        value={generatedPrompt} 
                                        onChange={setGeneratedPrompt}
                                        variables={variables}
                                        onVariableUpdate={handleVariableEditFromEditor}
                                        lang={language}
                                    />
                                </>
                            )}
                        </div>
                    </div>
                )}


                <SavedPrompts 
                    history={history}
                    onSelect={handleSelectHistoryItem}
                    onDelete={handleDeleteHistoryItem}
                    lang={language}
                />
            </div>
        </div>
    );
};

export default App;

import React from 'react';
import { MicrophoneIcon, SparklesIcon } from './Icons';

interface InputFieldProps {
    label: string;
    value: string;
    onChange: (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => void;
    placeholder: string;
    helpText: string;
    isTextarea?: boolean;
    required?: boolean;
    onMicClick?: () => void;
    isListening?: boolean;
    micSupported?: boolean;
    onAutoGenerate?: () => void; // New prop for the magic wand
}

const InputField: React.FC<InputFieldProps> = ({ 
    label, 
    value, 
    onChange, 
    placeholder, 
    helpText, 
    isTextarea = false, 
    required = false,
    onMicClick,
    isListening = false,
    micSupported = false,
    onAutoGenerate,
}) => {
    // Generate a unique ID for the input to connect the label for accessibility
    const inputId = `input-${label.replace(/\s+/g, '-').toLowerCase()}`;

    const commonInputClasses = `
        block w-full rounded-lg border appearance-none focus:outline-none focus:ring-0 peer transition-colors duration-200 
        bg-white border-gray-300 text-gray-900 focus:border-blue-500 group-hover:border-gray-400
        shadow-sm
        ${(micSupported || onAutoGenerate) ? "pr-20" : ""} 
    `;
    // Increased padding-right to accommodate two buttons if needed

    return (
        <div className="flex flex-col gap-2">
            <div className="relative group">
                {isTextarea ? (
                    <textarea
                        id={inputId}
                        value={value}
                        onChange={onChange}
                        placeholder=" " // A space is needed for the :placeholder-shown selector to work
                        required={required}
                        rows={4}
                        className={`${commonInputClasses} px-3 pt-6 pb-2 resize-none`}
                    />
                ) : (
                    <input
                        type="text"
                        id={inputId}
                        value={value}
                        onChange={onChange}
                        placeholder=" "
                        required={required}
                        className={`${commonInputClasses} h-14 px-3 pt-5`}
                    />
                )}
                <label
                    htmlFor={inputId}
                    className={`absolute text-blue-600 bg-white px-1 duration-300 transform -translate-y-3 scale-75 top-4 z-10 origin-[0] left-3
                               peer-placeholder-shown:scale-100
                               peer-placeholder-shown:translate-y-0
                               peer-placeholder-shown:text-gray-500
                               peer-focus:scale-75
                               peer-focus:-translate-y-3
                               peer-focus:text-blue-600
                               pointer-events-none font-medium tracking-wide`}
                >
                    {label} {required && <span className="text-red-500">*</span>}
                </label>

                <div className="absolute right-3 top-3 flex items-center gap-1">
                    {onAutoGenerate && (
                        <button
                            type="button"
                            onClick={onAutoGenerate}
                            className="p-1.5 rounded-full text-indigo-500 hover:text-white hover:bg-indigo-500 transition-colors duration-300"
                            title="Autocompletar con IA"
                            aria-label="Generar contenido con IA"
                        >
                            <SparklesIcon />
                        </button>
                    )}

                    {micSupported && (
                        <button
                            type="button"
                            onClick={onMicClick}
                            className={`p-1.5 rounded-full transition-colors ${isListening ? 'text-red-500 bg-red-100 animate-pulse' : 'text-gray-400 hover:text-gray-600'}`}
                            aria-label="Activar dictado por voz"
                            title="Dictar por voz"
                        >
                            <MicrophoneIcon />
                        </button>
                    )}
                </div>
            </div>
            <p className="text-xs text-gray-500 ml-1">{helpText}</p>
        </div>
    );
};

export default InputField;

import React, { useState } from 'react';
import { PromptHistoryItem } from '../types';
import { HistoryIcon, TrashIcon, DownloadIcon, PdfIcon, ChevronDownIcon, ChevronUpIcon, SearchIcon } from './Icons';

interface SavedPromptsProps {
    history: PromptHistoryItem[];
    onSelect: (item: PromptHistoryItem) => void;
    onDelete: (id: string) => void;
}

const SavedPrompts: React.FC<SavedPromptsProps> = ({ history, onSelect, onDelete }) => {
    const [expandedId, setExpandedId] = useState<string | null>(null);
    const [searchQuery, setSearchQuery] = useState<string>('');

    const handleToggleExpand = (id: string) => {
        setExpandedId(currentId => (currentId === id ? null : id));
    };

    // Sort prompts by timestamp, newest first
    const sortedHistory = [...history].sort((a, b) => b.timestamp - a.timestamp);

    // Filter prompts based on search query
    const filteredHistory = sortedHistory.filter(item => {
        const query = searchQuery.toLowerCase();
        if (!query) return true;

        const nicheMatch = (item.niche || '').toLowerCase().includes(query);
        const roleMatch = (item.promptData?.agentRole || '').toLowerCase().includes(query);
        const promptMatch = (item.generatedPrompt || '').toLowerCase().includes(query);

        return nicheMatch || roleMatch || promptMatch;
    });

    const handleExportMarkdown = (items: PromptHistoryItem[]) => {
        let markdownContent = "# Mi Base de Datos de Prompts\n\n";

        items.forEach(item => {
            markdownContent += `## Prompt para: ${item.niche || 'Sin Nicho'}\n\n`;
            markdownContent += `**Fecha:** ${new Date(item.timestamp).toLocaleString('es-ES')}\n\n`;
            markdownContent += "### Datos de Entrada:\n";
            markdownContent += "```json\n" + JSON.stringify(item.promptData, null, 2) + "\n```\n\n";
             if (item.variables && item.variables.length > 0) {
                markdownContent += "### Variables Dinámicas:\n";
                markdownContent += "```json\n" + JSON.stringify(item.variables.reduce((acc, v) => ({...acc, [v.name]: v.value}), {}), null, 2) + "\n```\n\n";
            }
            markdownContent += "### Prompt Generado:\n";
            markdownContent += item.generatedPrompt + "\n\n";
            markdownContent += "---\n\n";
        });

        const blob = new Blob([markdownContent], { type: 'text/markdown;charset=utf-8' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = 'deepcode-prompts.md';
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
    };

    const handlePrint = () => {
        const content = document.getElementById('history-print-area');
        if (!content) return;

         // Create a hidden iframe
        const iframe = document.createElement('iframe');
        iframe.style.position = 'fixed';
        iframe.style.right = '0';
        iframe.style.bottom = '0';
        iframe.style.width = '0';
        iframe.style.height = '0';
        iframe.style.border = '0';
        document.body.appendChild(iframe);

        const doc = iframe.contentWindow?.document;
        if (!doc) return;

        // Clone content but strip classes that hide it
        const contentClone = content.cloneNode(true) as HTMLElement;
        const hiddenElements = contentClone.querySelectorAll('.hidden');
        hiddenElements.forEach(el => el.classList.remove('hidden'));

        // Remove no-print elements from clone
        const noPrintElements = contentClone.querySelectorAll('.no-print');
        noPrintElements.forEach(el => el.remove());

        // Helper to get all row content even if not expanded in UI

        doc.open();
        doc.write(`
            <!DOCTYPE html>
            <html>
            <head>
                <title>Historial de Prompts</title>
                <style>
                    body { font-family: 'Helvetica', 'Arial', sans-serif; color: #000; background: #fff; padding: 20px; font-size: 10pt; }
                    h1 { font-size: 20px; border-bottom: 2px solid #000; padding-bottom: 10px; margin-bottom: 20px; }
                    table { width: 100%; border-collapse: collapse; margin-top: 20px; }
                    th, td { border: 1px solid #ddd; padding: 8px; text-align: left; vertical-align: top; }
                    th { background-color: #f2f2f2; font-weight: bold; }
                    .tag { background: #eee; padding: 2px 5px; border-radius: 3px; border: 1px solid #ccc; font-size: 0.85em; }
                    .timestamp { color: #666; font-size: 0.9em; }

                    /* Hide utilities that might have slipped through */
                    button, input { display: none !important; }
                </style>
            </head>
            <body>
                <h1>Historial de Procesamiento</h1>
                ${contentClone.innerHTML}
            </body>
            </html>
        `);
        doc.close();

        iframe.onload = () => {
             setTimeout(() => {
                iframe.contentWindow?.focus();
                iframe.contentWindow?.print();
                setTimeout(() => {
                    document.body.removeChild(iframe);
                }, 1000);
            }, 500);
        };
    };

    const renderDetail = (label: string, value: string | undefined | null, isPreWrap = false) => {
        if (!value || value.trim() === '') return null;
        return (
            <div>
                <dt className="font-bold text-blue-600 text-xs uppercase tracking-wider mb-1">{label}</dt>
                <dd className={`text-gray-700 text-sm ${isPreWrap ? 'whitespace-pre-wrap' : ''}`}>{value}</dd>
            </div>
        );
    };


    return (
        <section id="history-print-area" className="mt-12">
            <div className="flex flex-col md:flex-row justify-between items-center gap-6 mb-8 no-print">
                <div className="text-center md:text-left flex-shrink-0">
                    <h2 className="text-2xl font-bold text-gray-800 flex items-center justify-center sm:justify-start gap-3 uppercase tracking-wide">
                        <span className="w-1 h-6 bg-indigo-500 rounded-full"></span>
                        Processing History
                    </h2>
