                            >
                                <PdfIcon />
                                Print
                            </button>
                        </div>
                    </div>
                )}
            </div>

            <div className="print-header-content hidden">
                 <h2 className="text-2xl font-bold">System Prompt Database</h2>
            </div>

            {history.length === 0 ? (
                <div className="text-center py-12 bg-white border border-dashed border-gray-300 rounded-xl no-print">
