import { CheckIcon, CloseIcon } from './Icons';

interface MarkdownEditorProps {
    value: string;
    onChange: (value: string) => void;
    variables?: DynamicVariable[];
    onVariableUpdate?: (oldName: string, newName: string, newValue: string) => void;
}

interface EditingVarState {
    name: string;
    originalName: string;
    value: string;
    rect: DOMRect;
}

const MarkdownEditor: React.FC<MarkdownEditorProps> = ({ value, onChange, variables = [], onVariableUpdate }) => {
    const [activeTab, setActiveTab] = useState<'preview' | 'edit'>('preview');
    const [editingVar, setEditingVar] = useState<EditingVarState | null>(null);

    // Refs for the popover logic
    const popoverRef = useRef<HTMLDivElement>(null);

    const tabClasses = (tabName: 'preview' | 'edit') => 
        `px-4 py-2 text-xs font-bold uppercase tracking-wider rounded-t-lg transition-colors border-t border-x ${
            activeTab === tabName 
            ? 'bg-white border-gray-200 text-blue-600 border-b-transparent' 
            : 'bg-gray-100 border-transparent text-gray-500 hover:text-gray-700 border-b-gray-200'
        }`;

    // Regex to find {{variable_name}}
    const VARIABLE_REGEX = /(\{\{[a-zA-Z0-9_]+\}\})/g;

    // Handle click outside popover to close it
    useEffect(() => {
        const handleClickOutside = (event: MouseEvent) => {
            if (popoverRef.current && !popoverRef.current.contains(event.target as Node)) {
                setEditingVar(null);
            }
        };
        if (editingVar) {
            document.addEventListener('mousedown', handleClickOutside);
        }
        return () => {
            document.removeEventListener('mousedown', handleClickOutside);
        };
    }, [editingVar]);

    const handleVariableClick = (varName: string, e: React.MouseEvent<HTMLSpanElement>) => {
        e.preventDefault();
        e.stopPropagation();

        const rect = e.currentTarget.getBoundingClientRect();
        // Clean the name (remove {{ and }})
        const cleanName = varName.replace(/[{}]/g, '');

        // Find current value in props if it exists
        const currentVar = variables.find(v => v.name === cleanName);
        const val = currentVar ? currentVar.value : '';

        setEditingVar({
            name: cleanName,
            originalName: cleanName,
            value: val,
            rect: rect
        });
    };

    const handleSaveVariable = () => {
        if (editingVar && onVariableUpdate) {
            onVariableUpdate(editingVar.originalName, editingVar.name, editingVar.value);
            setEditingVar(null);
        }
    };

    // Helper to recursively parse children and wrap {{variables}}
    const renderContentWithVariables = (children: React.ReactNode): React.ReactNode => {
        return React.Children.map(children, child => {
            if (typeof child === 'string') {
                const parts = child.split(VARIABLE_REGEX);
                return parts.map((part, i) => {
                    if (part.match(VARIABLE_REGEX)) {
                        return (
                            <span 
                                key={i}
                                onClick={(e) => handleVariableClick(part, e)}
                                className="inline-block bg-purple-100 text-purple-700 border border-purple-200 rounded px-1.5 py-0.5 mx-0.5 cursor-pointer hover:bg-purple-200 hover:border-purple-300 transition-colors select-none text-[0.9em] font-mono shadow-sm"
                                title="Clic para editar variable"
                            >
                                {part}
                            </span>
                        );
                    }
                    return part;
                });
            }
            // Recursively process elements
            if (React.isValidElement(child)) {
                const props = child.props as { children?: React.ReactNode };
                if (props.children) {
                    return React.cloneElement(child as React.ReactElement<any>, {
                        children: renderContentWithVariables(props.children)
                    });
                }
            }
            return child;
        });
    };

    // Custom renderers for ReactMarkdown to intercept text
    const customRenderers = {
        p: ({ children }: any) => <p className="mb-4">{renderContentWithVariables(children)}</p>,
        li: ({ children }: any) => <li className="mb-1">{renderContentWithVariables(children)}</li>,
        h1: ({ children }: any) => <h1 className="text-2xl font-bold mb-4 border-b border-gray-200 pb-2 text-gray-900">{renderContentWithVariables(children)}</h1>,
        h2: ({ children }: any) => <h2 className="text-xl font-bold mb-3 mt-6 text-blue-700 uppercase tracking-wide">{renderContentWithVariables(children)}</h2>,
        h3: ({ children }: any) => <h3 className="text-lg font-bold mb-2 mt-4 text-gray-800">{renderContentWithVariables(children)}</h3>,
        blockquote: ({ children }: any) => <blockquote className="border-l-4 border-blue-500 pl-4 italic text-gray-600 my-4 bg-blue-50 p-2">{renderContentWithVariables(children)}</blockquote>,
    };


    return (
        <div className="relative">
            {/* Tabs are not printed */}
            <div className="flex items-end gap-0 mb-0 border-b border-gray-200 no-print">
                <button onClick={() => setActiveTab('preview')} className={tabClasses('preview')}>
                    Preview Output
                </button>
                <button onClick={() => setActiveTab('edit')} className={tabClasses('edit')}>
                    Raw Markdown
                </button>
            </div>

            <div className="bg-white rounded-b-xl p-1">
                {/* Edit View (Textarea) - not printed */}
                <div className={`${activeTab === 'edit' ? 'block' : 'hidden'} no-print`}>
                    <textarea
                        value={value}
                        onChange={(e) => onChange(e.target.value)}
                        className="w-full h-96 p-4 rounded-md bg-white border border-gray-300 text-gray-800 font-mono text-sm focus:outline-none focus:border-blue-500 resize-y leading-relaxed"
                        aria-label="Editor de Markdown"
                    />
                </div>

                {/* Preview View (ReactMarkdown) */}
                <div className={`${activeTab === 'preview' ? 'block' : 'hidden'} print:block bg-white rounded-lg min-h-[384px] border border-gray-100`}>
                     <div className="prose-styles prompt-content-for-print p-6">
                        <ReactMarkdown 
                            remarkPlugins={[remarkGfm]}
                            components={customRenderers}
                        >
                            {value}
                        </ReactMarkdown>
                    </div>
                </div>
            </div>

            {/* Editing Popover */}
            {editingVar && (
                <div 
                    className="fixed z-50 bg-white rounded-lg shadow-xl border border-gray-200 p-3 w-72 flex flex-col gap-3 animate-in fade-in zoom-in-95 duration-200"
                    style={{
                        // Position relative to viewport using the rect
                        top: Math.max(10, editingVar.rect.top - 170) + 'px', // Above the element
                        left: Math.min(window.innerWidth - 300, Math.max(10, editingVar.rect.left)) + 'px'
                    }}
                    ref={popoverRef}
                >
                    <div className="flex justify-between items-center border-b border-gray-100 pb-2">
                        <span className="text-xs font-bold text-purple-600 uppercase tracking-wider">Edit Variable</span>
                        <button onClick={() => setEditingVar(null)} className="text-gray-400 hover:text-gray-600">
                            <CloseIcon />
                        </button>
                    </div>

                    <div>
                        <label className="block text-[10px] text-gray-500 mb-1 uppercase tracking-wider">Variable Name</label>
                        <div className="flex items-center bg-gray-50 rounded border border-gray-200 px-2">
                            <span className="text-purple-500 font-mono text-sm">{`{{`}</span>
                            <input 
                                type="text" 
                                value={editingVar.name}
                                onChange={(e) => setEditingVar({...editingVar, name: e.target.value.replace(/[^a-zA-Z0-9_]/g, '')})}
                                className="bg-transparent border-none text-gray-800 text-sm w-full focus:ring-0 px-0.5 font-mono"
                            />
                            <span className="text-purple-500 font-mono text-sm">{`}}`}</span>
                        </div>
                    </div>

                    <div>
                        <label className="block text-[10px] text-gray-500 mb-1 uppercase tracking-wider">Value</label>
                        <input 
                            type="text" 
                            value={editingVar.value}
                            onChange={(e) => setEditingVar({...editingVar, value: e.target.value})}
                            placeholder="Enter value..."
                            className="w-full bg-white border border-gray-300 rounded px-2 py-1.5 text-sm text-gray-800 focus:border-purple-500 focus:outline-none focus:ring-1 focus:ring-purple-500"
                        />
                    </div>

                    <button 
                        onClick={handleSaveVariable}
                        className="flex items-center justify-center gap-2 bg-purple-600 hover:bg-purple-700 text-white text-xs font-bold py-2 rounded transition-colors mt-1 uppercase tracking-wide shadow-md"
                    >
                        <CheckIcon className="w-3 h-3" />
                        Update System
                    </button>

                    {/* Arrow pointing down */}
                    <div 
                        className="absolute -bottom-2 left-4 w-4 h-4 bg-white border-b border-r border-gray-200 transform rotate-45"
                        style={{ left: Math.min(270, Math.max(10, editingVar.rect.width/2)) + 'px' }} 
                    />
                </div>
            )}
        </div>
    );
};

export default MarkdownEditor;

import React, { useState } from 'react';
import { DynamicVariable } from '../types';
import { PlusIcon, TrashIcon, MicrophoneIcon } from './Icons';

interface DynamicVariablesProps {
    variables: DynamicVariable[];
    onAdd: () => void;
    onUpdate: (id: string, field: 'name' | 'value', value: string) => void;
    onDelete: (id: string) => void;
    onMicClick: (fieldIdentifier: string) => void;
    listeningField: string | null;
    micSupported: boolean;
}

const PREDEFINED_VARIABLES = [
    { value: 'nombre_cliente', label: 'Nombre del Cliente' },
    { value: 'nombre_agente', label: 'Nombre del Agente' },
    { value: 'empresa_cliente', label: 'Empresa del Cliente' },
    { value: 'fecha_actual', label: 'Fecha Actual' },
    { value: 'hora_actual', label: 'Hora Actual' },
    { value: 'numero_pedido', label: 'Número de Pedido' },
    { value: 'producto_servicio', label: 'Producto/Servicio' },
    { value: 'motivo_llamada', label: 'Motivo de la Llamada' },
];
const PREDEFINED_VALUES = PREDEFINED_VARIABLES.map(p => p.value);


const DynamicVariables: React.FC<DynamicVariablesProps> = ({ variables, onAdd, onUpdate, onDelete, onMicClick, listeningField, micSupported }) => {
    const [customEntryId, setCustomEntryId] = useState<string | null>(null);

    const handleNameChange = (id: string, name: string) => {
        // Allow only letters, numbers, and underscores
        const sanitizedName = name.replace(/[^a-zA-Z0-9_]/g, '');
        onUpdate(id, 'name', sanitizedName);
    }

    return (
        <div className="flex flex-col gap-2">
            <div>
                <label className="font-semibold text-gray-800">Variables Dinámicas</label>
                <p className="text-xs text-gray-500">
                    Define variables para reutilizar este prompt. Úsalas en los campos de arriba con la sintaxis <code className="bg-gray-100 text-indigo-600 px-1 py-0.5 rounded-sm text-[11px] border border-gray-200">{`{{nombre_variable}}`}</code>.
                </p>
            </div>

            <div className="space-y-3 mt-2">
                {variables.map((variable, index) => {
                    const isPredefined = PREDEFINED_VALUES.includes(variable.name);
                    const isCustom = variable.name && !isPredefined;
                    const showCustomInput = customEntryId === variable.id || isCustom;

                    return (
                        <div key={variable.id} className="flex items-center gap-2 p-3 bg-gray-50 rounded-lg border border-gray-200">
                            <div className="flex-1 relative">
                                {showCustomInput ? (
                                    <input
                                        type="text"
                                        value={variable.name}
                                        onChange={(e) => handleNameChange(variable.id, e.target.value)}
                                        placeholder="nombre_personalizado"
                                        className="w-full bg-white border border-gray-300 rounded-md p-2 pr-10 text-sm text-gray-800 focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 placeholder-gray-400"
                                        aria-label={`Nombre de la variable personalizada ${index + 1}`}
                                    />
                                ) : (
                                    <select
                                        value={variable.name}
                                        onChange={(e) => {
                                            if (e.target.value === 'CUSTOM') {
                                                setCustomEntryId(variable.id);
                                                onUpdate(variable.id, 'name', '');
                                            } else {
                                                onUpdate(variable.id, 'name', e.target.value);
                                                setCustomEntryId(null);
                                            }
                                        }}
                                        className="w-full bg-white border border-gray-300 rounded-md p-2 text-sm text-gray-800 focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 appearance-none"
                                        aria-label={`Nombre de la variable ${index + 1}`}
                                    >
                                        <option value="" disabled>Selecciona una variable...</option>
                                        {PREDEFINED_VARIABLES.map(opt => (
                                            <option key={opt.value} value={opt.value}>{opt.label}</option>
                                        ))}
                                        <option value="CUSTOM" className="font-bold text-indigo-600">Otra (Personalizada)...</option>
                                    </select>
                                )}
                                {showCustomInput && micSupported && (
                                    <button
                                        type="button"
                                        onClick={() => onMicClick(`variable-name-${variable.id}`)}
                                        className={`absolute right-2 top-1/2 -translate-y-1/2 p-1 rounded-full transition-colors ${listeningField === `variable-name-${variable.id}` ? 'text-indigo-600 bg-indigo-100' : 'text-gray-400 hover:text-gray-600'}`}
                                        aria-label={`Dictar nombre de variable ${index + 1}`}
                                    >
                                        <MicrophoneIcon />
                                    </button>
                                )}
                            </div>
                            <div className="flex-1 relative">
                                <input
                                    type="text"
                                    value={variable.value}
                                    onChange={(e) => onUpdate(variable.id, 'value', e.target.value)}
                                    placeholder="Valor de Ejemplo"
                                    className="w-full bg-white border border-gray-300 rounded-md p-2 pr-10 text-sm text-gray-800 focus:ring-1 focus:ring-indigo-500 focus:border-indigo-500 placeholder-gray-400"
                                    aria-label={`Valor de la variable ${index + 1}`}
                                />
                                {micSupported && (
                                    <button
                                        type="button"
                                        onClick={() => onMicClick(`variable-value-${variable.id}`)}
                                        className={`absolute right-2 top-1/2 -translate-y-1/2 p-1 rounded-full transition-colors ${listeningField === `variable-value-${variable.id}` ? 'text-indigo-600 bg-indigo-100' : 'text-gray-400 hover:text-gray-600'}`}
                                        aria-label={`Dictar valor de variable ${index + 1}`}
                                    >
                                        <MicrophoneIcon />
                                    </button>
                                )}
                            </div>
                            <button
                                type="button"
                                onClick={() => onDelete(variable.id)}
                                className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-full transition-colors"
                                aria-label={`Eliminar variable ${index + 1}`}
                            >
                                <TrashIcon />
                            </button>
                        </div>
                    )
                })}
            </div>

            <button
                type="button"
                onClick={onAdd}
                className="flex items-center justify-center gap-2 mt-2 px-4 py-2 bg-gray-100 hover:bg-indigo-50 text-gray-600 hover:text-indigo-600 font-semibold rounded-lg transition-colors text-sm border border-gray-200 hover:border-indigo-200"
            >
                <PlusIcon />
                Añadir Variable
            </button>
        </div>
    );
};

export default DynamicVariables;

import React, { useState, useEffect } from 'react';
import { CloseIcon, CopyIcon, CheckIcon } from './Icons';

interface ShareModalProps {
    isOpen: boolean;
    onClose: () => void;
    link: string;
}

const ShareModal: React.FC<ShareModalProps> = ({ isOpen, onClose, link }) => {
    const [isCopied, setIsCopied] = useState(false);

    useEffect(() => {
        if (!isOpen) {
            setIsCopied(false);
        }
    }, [isOpen]);

    const handleCopy = () => {
        navigator.clipboard.writeText(link);
        setIsCopied(true);
        setTimeout(() => setIsCopied(false), 2000);
    };

    if (!isOpen) return null;

    return (
        <div
            className="fixed inset-0 bg-gray-800/50 backdrop-blur-sm z-50 flex items-center justify-center"
            onClick={onClose}
            aria-modal="true"
            role="dialog"
        >
            <div
                className="bg-white/95 backdrop-blur-xl rounded-2xl shadow-2xl w-full max-w-lg border border-gray-200 m-4 flex flex-col"
                onClick={(e) => e.stopPropagation()}
            >
                <header className="flex items-center justify-between p-4 border-b border-gray-100">
                    <h2 className="text-xl font-bold text-gray-800">Compartir Prompt</h2>
                    <button onClick={onClose} className="p-1 text-gray-400 hover:text-gray-600 rounded-full hover:bg-gray-100 transition-colors" aria-label="Cerrar modal">
                        <CloseIcon />
                    </button>
                </header>
                <div className="p-6">
                    <p className="text-gray-600 mb-4 text-sm">
                        Cualquier persona con este enlace podrá ver y cargar una copia de tu prompt generado.
                    </p>
                    <div className="flex items-center gap-2">
                        <input
                            type="text"
                            value={link}
                            readOnly
                            className="w-full bg-gray-50 border border-gray-300 rounded-md p-2 text-gray-700 text-sm truncate"
                            aria-label="Enlace para compartir"
                        />
                        <button
                            onClick={handleCopy}
                            className={`flex-shrink-0 flex items-center gap-2 px-4 py-2 text-white font-semibold rounded-lg transition-colors text-sm ${isCopied ? 'bg-green-600 hover:bg-green-700' : 'bg-blue-600 hover:bg-blue-700'}`}
                        >
                            {isCopied ? <CheckIcon /> : <CopyIcon />}
                            {isCopied ? 'Copiado' : 'Copiar'}
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default ShareModal;

